(91904, 'frFR', '', 'Avez-vous des nouvelles de mon fils, Durotan ?', 19865),
(91905, 'frFR', '', 'Cette guerre finira-t-elle un jour ?', 19865),
(91906, 'frFR', '', 'Comment se porte mon fils, Durotan ?', 19865),
(91907, 'frFR', '', 'Nous n’étions pas obligés d’en arriver là.', 19865),
(91908, 'frFR', '', 'Ces personnes sont sous ma protection.', 19865),
(91909, 'frFR', '', 'Vous ne nuirez plus à mon peuple.', 19865),
(91910, 'frFR', '', 'Je regrette la manière dont ceci se termine.', 19865),
(91911, 'frFR', '', 'Garad… Je viens à toi…', 19865),
(91912, 'frFR', '', 'Je ne vous laisserai pas faire de mal à mon peuple.', 19865),
(91917, 'frFR', 'La Horde a pris le contrôle des ruines Draeneï !', '', 19865),
